import type { jsPDF } from 'jspdf';

export interface PdfBackgroundAsset {
  readonly dataUri: string;
  readonly format: 'JPEG';
  readonly width: number;
  readonly height: number;
  readonly aspectRatio: number;
}

/**
 * Approved SRMCON 2027 common A4 background (1055x1491, sRGB) encoded as a
 * high-quality lossless-subsampling JPEG (4:4:4) Data URI so browser PDFs,
 * downloads, and Base64 email attachments render identically with minimal payload size.
 */
export const SRMCON_PDF_BACKGROUND: PdfBackgroundAsset = {
  dataUri: 'data:image/jpeg;base64,',
  format: 'JPEG',
  width: 1055,
  height: 1491,
  aspectRatio: 1055 / 1491,
};

const A4_WIDTH_MM = 210;
const A4_HEIGHT_MM = 297;
const BACKGROUND_IMAGE_ALIAS = 'SRMCON_COMMON_BG';

/**
 * Renders the full-page SRMCON 2027 institutional background onto the active PDF page
 * while strictly preserving its natural aspect ratio without stretching or cropping.
 * Must be called immediately after page creation before drawing any foreground content.
 */
export function drawCommonPageBackground(doc: jsPDF): void {
  const drawH = A4_HEIGHT_MM;
  const drawW = drawH * SRMCON_PDF_BACKGROUND.aspectRatio;
  const drawX = (A4_WIDTH_MM - drawW) / 2;
  doc.addImage(
    SRMCON_PDF_BACKGROUND.dataUri,
    SRMCON_PDF_BACKGROUND.format,
    drawX,
    0,
    drawW,
    drawH,
    BACKGROUND_IMAGE_ALIAS,
    'FAST'
  );
}
